function isObject(value) {
	return value && typeof value === 'object' && !Array.isArray(value);
}

function findKey(obj, predicate, label) {
	const key = Object.keys(obj).find(key => predicate(obj[key], key));
	if (!key) throw new Error(`tasks: failed to detect ${label} field`);
	return key;
}

function textMapValueEquals(language, value, text) {
	return value && language[value] === text;
}

function objectHasValue(obj, expected) {
	return Object.values(obj).includes(expected);
}

function objectHasTextValue(language, obj, text) {
	return Object.values(obj).some(value => textMapValueEquals(language, value, text));
}

function objectHasArrayValue(obj, expected, compareAsString = false) {
	return Object.values(obj).some(value =>
		Array.isArray(value) && value.some(item =>
			compareAsString ? String(item) === String(expected) : item === expected));
}

function objectHasPositionParam(obj) {
	return Object.values(obj).some(value =>
		Array.isArray(value) && value.some(param => typeof param === 'string' && param.startsWith('[')));
}

function objectHasStringValueIncluding(obj, expected) {
	return Object.values(obj).some(value => typeof value === 'string' && value.includes(expected));
}

function getObjectArrayValues(obj) {
	return Object.values(obj).filter(value => Array.isArray(value) && value.some(isObject));
}

